/*
 * File Name: tasks.provider.test.ts
 * Description: Verifies the Pact consumer contract (generated by
 *   task.pact.test.ts) against the real Express backend, wired to an
 *   in-memory Task store. This is the missing half of the
 *   consumer-driven contract: the consumer test writes
 *   pacts/Auxilia-Frontend-Auxilia-API.json; this test replays it against
 *   the provider and fails the build on any divergence in status codes,
 *   headers or body shape.
 *
 *   Runs in CI as part of `npm test` / `npm run test:coverage` and locally
 *   with `npm run test:contract`.
 *
 *   Authentication note: the pact replays the consumer's recorded token
 *   ("Bearer example-access-token"). verifyAccessToken is therefore stubbed
 *   to accept that exact token; everything else (routing, validation,
 *   controller, service, repository, session handling) is the real code.
 */

import { afterAll, beforeAll, describe, it, vi } from "vitest";
import type { Server } from "node:http";
import path from "node:path";

// Opt out of the verifier's anonymous usage tracking.
process.env.PACT_DO_NOT_TRACK = "true";

// Hoisted so the vi.mock factories can share state with the state handlers.
const store = vi.hoisted(() => ({
  tasks: [] as Array<Record<string, any>>,
}));

const PACT_USER_ID = "33333333-3333-4333-8333-333333333333";

vi.mock("../../src/modules/auth/auth.model.js", async () => {
  const { authModelMock } = await import("../helpers/authMocks.js");
  return authModelMock();
});

vi.mock("../../src/modules/auth/session.model.js", async () => {
  const { sessionModelMock } = await import("../helpers/authMocks.js");
  return sessionModelMock();
});

vi.mock("../../src/modules/tasks/task.model.js", async () => {
  const { createInMemoryTaskModel } =
    await import("../helpers/inMemoryTaskModel.js");
  return createInMemoryTaskModel(store);
});

vi.mock("../../src/shared/utils/tokens.js", async () => {
  const actual = await vi.importActual<
    typeof import("../../src/shared/utils/tokens.js")
  >("../../src/shared/utils/tokens.js");

  return {
    ...actual,
    // Only the token recorded in the pact is accepted; anything else falls
    // through to the real verifier.
    verifyAccessToken: (token: string) =>
      token === "example-access-token"
        ? {
            sub: PACT_USER_ID,
            email: "ada@example.com",
            jti: "pact-example-session",
            iss: "auxilia",
            iat: 1_700_000_000,
            exp: Math.floor(Date.now() / 1000) + 3600,
          }
        : actual.verifyAccessToken(token),
  };
});

import app from "../../src/app";
import { Verifier } from "@pact-foundation/pact";
import { User } from "../../src/modules/auth/auth.model.js";
import { AuthSession } from "../../src/modules/auth/session.model.js";
import { sessionCache } from "../../src/modules/auth/session.cache.js";
import { queryResult } from "../helpers/authMocks.js";

const userModel = User as any;
const sessionModel = AuthSession as any;

const seedAuthenticatedSession = () => {
  userModel.findById.mockReturnValue(
    queryResult({ _id: PACT_USER_ID, email: "ada@example.com", role: "user" }),
  );
  sessionModel.findById.mockReturnValue(
    queryResult({
      _id: "pact-example-session",
      userId: PACT_USER_ID,
      revokedAt: null,
      expiresAt: new Date(Date.now() + 60 * 60 * 1000),
      userAgent: "pact-verifier",
      createdAt: new Date(),
      lastUsedAt: new Date(),
    }),
  );
};

const seedOneTask = () => {
  store.tasks.length = 0;
  store.tasks.push({
    _id: "task-123",
    userId: PACT_USER_ID,
    title: "Complete CI/CD assignment",
    description: "Finish the deployment report",
    course: "",
    tags: [],
    groupId: null,
    assigneeId: null,
    assigneeName: null,
    status: "todo",
    priority: "high",
    dueDate: null,
    reminderAt: null,
    completedAt: null,
    deletedAt: null,
    createdAt: new Date("2026-11-01T09:00:00.000Z"),
    updatedAt: new Date("2026-11-01T09:00:00.000Z"),
  });
};

let server: Server | null = null;
let providerBaseUrl = "";

beforeAll(async () => {
  // Authenticated requests: one user, one active session.
  seedAuthenticatedSession();
  sessionCache.clear();

  await new Promise<void>((resolve) => {
    server = app.listen(0, "127.0.0.1", () => resolve());
  });

  const address = server?.address();
  if (!address || typeof address === "string") {
    throw new Error("Failed to bind the provider app to an ephemeral port.");
  }

  providerBaseUrl = `http://127.0.0.1:${address.port}`;
});

afterAll(async () => {
  await new Promise<void>((resolve, reject) => {
    if (!server) return resolve();
    server.close((error) => (error ? reject(error) : resolve()));
  });
  server = null;
});

describe("Auxilia-API provider verification (Pact)", () => {
  it("satisfies the Auxilia-Frontend consumer contract", async () => {
    const pactPath = path.resolve(
      process.cwd(),
      "pacts/Auxilia-Frontend-Auxilia-API.json",
    );

    const verifier = new Verifier({
      provider: "Auxilia-API",
      providerBaseUrl,
      pactUrls: [pactPath],
      logLevel: "warn",
      stateHandlers: {
        "the authenticated user has at least one task": async () => {
          vi.resetAllMocks();
          sessionCache.clear();
          seedAuthenticatedSession();
          seedOneTask();
        },
        "the authenticated user can create tasks": async () => {
          vi.resetAllMocks();
          sessionCache.clear();
          seedAuthenticatedSession();
          store.tasks.length = 0;
        },
      },
    });

    // Rejects with the mismatch report when the contract is not met.
    const verificationResult = await verifier.verifyProvider();
    expect(verificationResult).toBeTruthy();
  }, 120_000);
});
